@import "@fontsource/ibm-plex-sans/400.css";
@import "@fontsource/ibm-plex-sans/500.css";
@import "@fontsource/ibm-plex-sans/600.css";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";
@import "tailwindcss" source("./");
@import "tw-animate-css";
@import "sonner/dist/styles.css";

@custom-variant dark (&:is(.dark *));

/*
 * shadcn's default neutral theme (new-york v4), light on :root and dark on .dark, plus the
 * few tokens the components add on top: inset and elevated surfaces, the status tones
 * and the border-as-shadow. ThemeProvider sets the class on <html>.
 */
:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);

  /* Additions: a field's sunken surface and a raised one (menus, toasts). */
  --inset: oklch(0.985 0 0);
  --elevated: oklch(1 0 0);
  /* Status tones: the colour, and a readable text colour on a 15% tint of it. */
  --signal: oklch(0.6 0.118 184.704);
  --signal-fg: oklch(0.42 0.09 184.704);
  --warn: oklch(0.769 0.165 70.08);
  --warn-fg: oklch(0.47 0.12 60);
  --danger: oklch(0.577 0.245 27.325);
  --danger-fg: oklch(0.505 0.213 27.518);
  --info: oklch(0.588 0.1 236);
  --offline: oklch(0.708 0 0);
  --scrollbar: oklch(0 0 0 / 18%);
  --shadow-border: 0 0 0 1px var(--border);
  --shadow-border-hover: 0 0 0 1px oklch(0.85 0 0);
  --shadow-elevated: 0 0 0 1px var(--border), 0 16px 40px -16px oklch(0 0 0 / 18%);
  --shadow-pinned: 4px 0 6px -4px oklch(0 0 0 / 15%);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);

  --inset: oklch(0.175 0 0);
  --elevated: oklch(0.235 0 0);
  --signal: oklch(0.696 0.17 162.48);
  --signal-fg: oklch(0.85 0.1 162.48);
  --warn: oklch(0.769 0.188 70.08);
  --warn-fg: oklch(0.9 0.1 85);
  --danger: oklch(0.704 0.191 22.216);
  --danger-fg: oklch(0.85 0.09 22.216);
  --info: oklch(0.72 0.09 236);
  --offline: oklch(0.556 0 0);
  --scrollbar: oklch(1 0 0 / 16%);
  --shadow-border: 0 0 0 1px var(--border);
  --shadow-border-hover: 0 0 0 1px oklch(1 0 0 / 18%);
  --shadow-elevated: 0 0 0 1px var(--border), 0 24px 48px -16px oklch(0 0 0 / 55%);
  --shadow-pinned: 4px 0 6px -4px oklch(0 0 0 / 60%);
}

@theme inline {
  --font-sans: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --color-inset: var(--inset);
  --color-elevated: var(--elevated);
  --color-signal: var(--signal);
  --color-signal-fg: var(--signal-fg);
  --color-warn: var(--warn);
  --color-warn-fg: var(--warn-fg);
  --color-danger: var(--danger);
  --color-danger-fg: var(--danger-fg);
  --color-online: var(--signal);
  --color-degraded: var(--warn);
  --color-offline: var(--offline);
  --color-info: var(--info);
  /* Opaque hover for pinned data-grid cells, so scrolled cells never show through. */
  --color-grid-pinned-hover: color-mix(in oklab, var(--secondary) 40%, var(--background));

  --shadow-border: var(--shadow-border);
  --shadow-border-hover: var(--shadow-border-hover);
  --shadow-elevated: var(--shadow-elevated);
  --shadow-pinned: var(--shadow-pinned);

  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
}

@layer base {
  * {
    @apply border-border;
    /* Thin, quiet scrollbars, so a wide table's own bar matches the dark surfaces. */
    scrollbar-width: thin;
    scrollbar-color: var(--scrollbar) transparent;
  }

  html {
    color-scheme: light;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    height: 100dvh;
    /* clip (not hidden): root must not be a scroll container — Chrome scroll
       restoration otherwise restores documentElement.scrollTop when nested
       panes (tree + settings) both overflow, shifting the shell up. */
    overflow: hidden;
    overflow: clip;
    overscroll-behavior: none;
  }

  body {
    @apply bg-background text-foreground font-sans;
    height: 100dvh;
    overflow: hidden;
    overflow: clip;
    overscroll-behavior: none;
  }

  html.dark {
    color-scheme: dark;
  }

  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  h1,
  h2,
  h3 {
    text-wrap: balance;
  }

  p {
    text-wrap: pretty;
  }

  :focus-visible {
    outline: 2px solid color-mix(in oklab, var(--ring) 70%, transparent);
    outline-offset: 2px;
  }

  input:focus-visible,
  select:focus-visible,
  textarea:focus-visible,
  input:focus,
  select:focus,
  textarea:focus {
    outline: none;
  }
}

@layer components {
  .app-toaster {
    font-family: var(--font-sans);
    --width: 20rem;
    --border-radius: var(--radius-sm);
    --normal-bg: var(--color-elevated);
    --normal-border: var(--color-border);
    --normal-text: var(--color-foreground);
    --success-bg: var(--color-elevated);
    --success-border: var(--color-border);
    --success-text: var(--color-foreground);
    --error-bg: var(--color-elevated);
    --error-border: var(--color-border);
    --error-text: var(--color-foreground);
    --warning-bg: var(--color-elevated);
    --warning-border: var(--color-border);
    --warning-text: var(--color-foreground);
  }

  .app-toaster [data-description] {
    color: var(--color-muted-foreground);
  }

  .app-toast {
    display: flex;
    width: var(--width);
    align-items: flex-start;
    gap: 0.75rem;
    padding: 0.75rem 2.25rem 0.75rem 0.75rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    background: var(--color-elevated);
    box-shadow: var(--shadow-elevated);
    color: var(--color-foreground);
    font-family: var(--font-sans);
  }

  .app-toast__content {
    min-width: 0;
    flex: 1;
  }

  .app-toast__title {
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1.25rem;
  }

  .app-toast__description {
    margin-top: 0.125rem;
    color: var(--color-muted-foreground);
    font-size: 0.75rem;
    line-height: 1rem;
  }

  .app-toast__icon {
    display: block;
    width: 0.5rem;
    height: 0.5rem;
    flex: none;
    margin-top: 0.375rem;
    overflow: hidden;
    border-radius: 99px;
    background: var(--color-muted-foreground);
    box-shadow: 0 0 10px color-mix(in oklab, var(--offline) 35%, transparent);
    color: transparent;
  }

  .app-toast__icon svg,
  .app-toast__icon img {
    display: none;
  }

  .app-toast__close {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    left: auto;
    display: flex;
    width: 1.5rem;
    height: 1.5rem;
    transform: none;
    align-items: center;
    justify-content: center;
    border: 0;
    border-radius: calc(var(--radius) - 6px);
    background: transparent;
    color: var(--color-muted-foreground);
    cursor: pointer;
    transition:
      color 150ms var(--ease-out),
      background-color 150ms var(--ease-out);
  }

  .app-toast__close:hover {
    background: var(--color-secondary);
    color: var(--color-foreground);
  }

  .app-toast--success .app-toast__icon {
    background: var(--color-signal);
    box-shadow: 0 0 10px color-mix(in oklab, var(--signal) 50%, transparent);
  }

  .app-toast--error .app-toast__icon {
    background: var(--color-danger);
    box-shadow: 0 0 10px color-mix(in oklab, var(--danger) 50%, transparent);
  }

  .app-toast--warning .app-toast__icon {
    background: var(--color-warn);
    box-shadow: 0 0 10px color-mix(in oklab, var(--warn) 45%, transparent);
  }

  .app-toast--info .app-toast__icon {
    background: var(--color-info);
    box-shadow: 0 0 10px color-mix(in oklab, var(--info) 45%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@keyframes pulse-live {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

.status-pulse {
  animation: pulse-live 1.8s var(--ease-out) infinite;
}

@media (prefers-reduced-motion: reduce) {
  .status-pulse {
    animation: none;
  }
}
